let CURRENT_LANG = 'en';

function getI18nText(key, replacements = {}, lang) {
  const chosenLang = (typeof lang === 'string' && I18N_TRANSLATIONS[lang]) ? lang : CURRENT_LANG;
  const dict = I18N_TRANSLATIONS[chosenLang] || I18N_TRANSLATIONS['en'];
  let text = dict[key] || I18N_TRANSLATIONS['en'][key] || key;
  for (const [k, v] of Object.entries(replacements)) {
    text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
  }
  return text;
}

function setLanguage(lang) {
  if (!I18N_TRANSLATIONS[lang]) lang = 'en';
  CURRENT_LANG = lang;
  try {
    localStorage.setItem('passportready_lang', lang);
  } catch (e) {}

  const dict = I18N_TRANSLATIONS[lang];
  if (typeof document !== 'undefined') {
    document.documentElement.lang = lang;
    document.documentElement.dir = dict.dir || 'ltr';

    // Apply translations to all DOM nodes with data-i18n
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const k = el.dataset.i18n;
      if (dict[k]) {
        if (el.dataset.i18nTarget === 'placeholder') {
          el.placeholder = dict[k];
        } else {
          el.innerHTML = dict[k];
        }
      }
    });
  }

  // Trigger language change event for dynamic components
  if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang, dict } }));
  }
}

// Export for Node and browser
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { I18N_TRANSLATIONS, I18N_METADATA, getI18nText, setLanguage };
}
if (typeof window !== 'undefined') {
  window.I18N_TRANSLATIONS = I18N_TRANSLATIONS;
  window.I18N_METADATA = I18N_METADATA;
  window.getI18nText = getI18nText;
  window.setLanguage = setLanguage;
}
